import {createElement} from "D:/projexts/moe-next/node_modules/.pnpm/react@19.2.8/node_modules/react/index.js";
import {cleanup,render,screen,waitFor} from "D:/projexts/moe-next/node_modules/.pnpm/@testing-library+react@16.3_2a46ce64b8cc64b21842ce81a682d490/node_modules/@testing-library/react/dist/index.js";
import {afterEach,it,expect} from "D:/projexts/moe-next/node_modules/.pnpm/vitest@4.1.10_@types+node@24.13.3_jsdom@30.0.1_yaml@2.9.0/node_modules/vitest/dist/index.js";
import {LiveEnvironments} from "D:/projexts/moe-next/apps/control-room/src/v2/ops/live-environments.tsx";
afterEach(cleanup);
const catalog=n=>({connection:'CONNECTED',detail:'',outcome:'GOALS',goals:Array.from({length:n},(_,i)=>({goalId:'goal-'+i}))});
const base={headers:{},pollMs:60000,readBackupList:async()=>({status:'BACKUPS',backups:[]}),readHealth:async environment=>({status:'DEPLOYMENTS_HEALTH',environment,state:'UP',lastProbe:null,lastError:null,incident:null,probeRefusal:null,rollbackSha:null,latencySeries:{points:[],windowMinutes:60},probeIntervalMs:60000})};
it.each(['ERROR','REFUSED'])('preserves deployment %s instead of claiming empty',async status=>{
render(createElement(LiveEnvironments,{...base,readCatalog:async()=>catalog(1),readDeploys:async()=>({status,code:'DEPLOYMENTS_RESPONSE_INVALID',layer:'CONTROL_ROOM_DEPLOY'})}));
await waitFor(()=>expect(screen.queryByTestId('cr.environments.loading')).toBeNull()); console.log('ENUMERATION_OBSERVATION',screen.queryByTestId('cr.environments.empty')?.textContent);
expect(screen.queryByTestId('cr.environments.refusal')?.textContent ?? '').toContain('DEPLOYMENTS_RESPONSE_INVALID @ CONTROL_ROOM_DEPLOY');
expect(screen.queryByTestId('cr.environments.empty')).toBeNull();
});
it('does not silently omit a deployed environment on goal 13',async()=>{
const asked=[];
render(createElement(LiveEnvironments,{...base,readCatalog:async()=>catalog(13),readDeploys:async goalRef=>{asked.push(goalRef);return {status:'DEPLOYMENTS',goalRef,environments:goalRef==='goal-12'?[{environment:'production',outcome:'DEPLOYED'}]:[]}}}));
await waitFor(()=>expect(screen.queryByTestId('cr.environments.loading')).toBeNull()); console.log('ENUMERATION_OBSERVATION',screen.queryByTestId('cr.environments.empty')?.textContent);
console.log('CAP_OBSERVATION',JSON.stringify({asked,empty:screen.queryByTestId('cr.environments.empty')?.textContent})); expect(asked).toHaveLength(13);
expect(screen.queryByTestId('cr.environments.card.production')?.getAttribute('data-status')).toBe('UP');
expect(screen.queryByTestId('cr.environments.empty')).toBeNull();
});

